Item.method_code:
const itm = document.item;
const isNew = ((itm.getAttribute('action') == 'add') || (itm.getAttribute('action') == 'create'));

if (!itm || !document.isEditMode || !isNew) {
	return;
}

const ownedByIdNd = itm.selectSingleNode('owned_by_id');
if (!ownedByIdNd) {
	const identityNd = aras.getItemByName('Identity', 'World');
	const identityId = identityNd.getAttribute('id');
	aras.setItemProperty(itm, 'owned_by_id', identityId);
	handleItemChange('owned_by_id', identityId);
}

const managedByIdNd = itm.selectSingleNode('managed_by_id');
if (!managedByIdNd) {
	const identityId = aras.getIsAliasIdentityIDForLoggedUser();
	aras.setItemProperty(itm, 'managed_by_id', identityId);
	handleItemChange('managed_by_id', identityId);
}
